begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(20);
select has_function('public','site_admin_get_cleanup_health',array['uuid'],'cleanup health has one actor-bound read RPC');
select ok(has_function_privilege('authenticated','public.site_admin_get_cleanup_health(uuid)','execute'),'authenticated callers may enter the native guard');
select ok(not has_function_privilege('anon','public.site_admin_get_cleanup_health(uuid)','execute'),'anonymous callers cannot execute cleanup health');
select ok(not has_function_privilege('service_role','public.site_admin_get_cleanup_health(uuid)','execute'),'service keys cannot replace the native admin actor');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid='public.site_admin_get_cleanup_health(uuid)'::regprocedure and a.grantee=0),'PUBLIC has no default execute');
select ok((select prosecdef and provolatile='s' and proconfig @> array['search_path=""','lock_timeout=1s'] from pg_proc where oid='public.site_admin_get_cleanup_health(uuid)'::regprocedure),'reader is stable, empty-search-path and lock-limited');
select is((select pronargs::integer from pg_proc where oid='public.site_admin_get_cleanup_health(uuid)'::regprocedure),1,'callers cannot select jobs, predicates or caps');
select ok((select relrowsecurity from pg_class where oid='private.profile_photo_objects'::regclass),'registry retains RLS');
select ok(not has_table_privilege('authenticated','private.profile_photo_objects','select'),'members cannot inspect private object rows');
select ok(not has_table_privilege('authenticated','private.profile_photo_objects','update'),'read RPC adds no object mutation grant');
select ok(not has_table_privilege('service_role','private.profile_photo_objects','select'),'existing service direct registry restriction remains');
select has_index('private','profile_photo_objects','profile_photo_objects_cleanup_eligible_idx','ready probes use the eligibility-time index');
select has_index('private','profile_photo_objects','profile_photo_objects_cleanup_service_lease_idx','lease probes use the service-only index');
select has_index('private','profile_photo_objects','profile_photo_objects_cleanup_failure_idx','failure probes use the last-failure index');
select has_index('private','profile_photo_objects','profile_photo_objects_expiry_idx','pending probe reuses its existing index');
select has_index('private','profile_photo_objects','profile_photo_objects_service_cleanup_idx','backoff probe reuses its existing index');
select ok(not has_function_privilege('authenticated','private.require_site_admin(text,uuid,boolean)','execute'),'private authority helper remains inaccessible');
select ok(not has_function_privilege('authenticated','public.profile_photo_cleanup_monitor_health()','execute'),'service monitor is not exposed to members');
select ok(has_function_privilege('service_role','public.profile_photo_cleanup_monitor_health()','execute'),'existing service monitor grant remains');
grant usage on schema extensions to authenticated;
set local request.jwt.claims = '{}';
set local role authenticated;
select throws_ok($$select public.site_admin_get_cleanup_health('15020000-0000-4000-8000-000000000001')$$,'PT401','admin_authentication_required','missing actor is rejected before operational reads');
reset role;
select * from finish();
rollback;
